<?php get_header(); $result = null; if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['oubei_quote_nonce']) && wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['oubei_quote_nonce'])), 'oubei_submit_quote')) { $result = oubei_handle_inquiry(wp_unslash($_POST), ['ip' => $_SERVER['REMOTE_ADDR'] ?? '']); } ?><main class="oubei-section"><div class="oubei-container"><p class="eyebrow">Contact</p><h1>Tell us what you need to seal.</h1><?php if ($result && $result['success']) : ?><p class="oubei-form-success">Thanks — your inquiry has been received.</p><?php elseif ($result) : ?><p class="oubei-form-error"><?php echo esc_html($result['error']); ?></p><?php endif; ?><form class="oubei-inquiry-form" method="post"><?php wp_nonce_field('oubei_submit_quote', 'oubei_quote_nonce'); ?><input type="text" name="website" tabindex="-1" autocomplete="off" aria-hidden="true" style="position:absolute;left:-9999px"><label>Name *<input required name="name"></label><label>Company *<input required name="company"></label><label>Email *<input required type="email" name="email"></label><label>Phone<input name="phone"></label><label>Country<input name="country"></label><label>Message *<textarea required name="message" rows="6"></textarea></label><button class="button button--accent" type="submit">Send inquiry</button></form></div></main><?php get_footer();
